WITH long_format AS (SELECT * FROM (SELECT id, status, discount, amount, shipping_fee FROM orders) src UNPIVOT INCLUDE NULLS (reading FOR metric_name IN (discount, amount, shipping_fee))) SELECT CASE WHEN reading >= 62 THEN 'HIGH' ELSE 'LOW' END AS reading_tier, status, ROUND(SUM(reading) / NULLIF(COUNT(CASE WHEN status = 'PENDING' THEN 1 END), 0), 2) AS reading_per_pending, COUNT(*) FILTER (WHERE status = 'CANCELLED') AS cancelled_rows, AVG(reading) AS avg_reading, MIN(reading) AS min_reading FROM long_format GROUP BY CASE WHEN reading >= 62 THEN 'HIGH' ELSE 'LOW' END, status HAVING cancelled_rows >= 1
